declarations.statement:
∀ {ι : Sort u_1} [inst : DecidableEq ι] {α : ι → Sort u_2} {β : ι → Sort u_3} {γ : ι → Sort u_4}
  (f : (i : ι) → α i → β i → γ i) (g : (i : ι) → α i) (h : (i : ι) → β i) (i : ι) (v : α i) (w : β i) (j : ι),
  f j (Function.update g i v j) (Function.update h i w j) = Function.update (fun k => f k (g k) (h k)) i (f i v w) j

declarations.doc:
The partial orders from `SemilatticeSup_mk'` and `SemilatticeInf_mk'` agree
if `sup` and `inf` satisfy the lattice absorption laws `sup_inf_self` (`a ⊔ a ⊓ b = a`)
and `inf_sup_self` (`a ⊓ (a ⊔ b) = a`).

declarations.statement:
{α : Type u} →
  [inst : Lattice α] →
    {P : α → Prop} → (∀ ⦃x y : α⦄, P x → P y → P (x ⊔ y)) → (∀ ⦃x y : α⦄, P x → P y → P (x ⊓ y)) → Lattice { x // P x }

∀ {α : Type u_1} {β : Type u_2} {γ : Type u_3} {δ : Type u_4} {s : Set α} {t : Set β} {f : α → β} {p₁ : α → γ}
  {p₂ : β → δ} {g : γ → δ},
  (∀ (a : α), p₂ (f a) = g (p₁ a)) → Set.BijOn f s t → Set.InjOn g (p₁ '' s) → Set.BijOn g (p₁ '' s) (p₂ '' t)

∀ {α : Type u_1} {β : Type u_2} {γ : Type u_3} {s : Set α} {t : Set β} {p : Set γ} {f : α → β} {g : β → γ} {f' : β → α}
  {g' : γ → β},
  Set.InvOn f' f s t → Set.InvOn g' g t p → Set.MapsTo f s t → Set.MapsTo g' p t → Set.InvOn (f' ∘ g') (g ∘ f) s p

∀ {α : Type u_1} {β : Type u_2} {p : β → Prop} [inst : DecidablePred p] {f : α ≃ Subtype p} {g₁ g₂ : Equiv.Perm α}
  {s : Set α},
  Set.LeftInvOn (⇑g₁) (⇑g₂) s → Set.LeftInvOn (⇑(g₁.extendDomain f)) (⇑(g₂.extendDomain f)) (Subtype.val ∘ ⇑f '' s)

∀ {α : Type u_1} {β : Type u_2} {p : β → Prop} [inst : DecidablePred p] {f : α ≃ Subtype p} {g₁ g₂ : Equiv.Perm α}
  {t : Set α},
  Set.RightInvOn (⇑g₁) (⇑g₂) t → Set.RightInvOn (⇑(g₁.extendDomain f)) (⇑(g₂.extendDomain f)) (Subtype.val ∘ ⇑f '' t)

∀ {α₁ : Type u_6} {α₂ : Type u_7} {β₁ : Type u_8} {β₂ : Type u_9} {s₁ : Set α₁} {s₂ : Set α₂} {t₁ : Set β₁}
